#[test]
fn test_table_offsets() {
    let mut fops = BinaryBasicFrops::new();
    fops.test_table_offsets();
}

#[test]
fn test_all_accessible_values() {
    let mut fops = BinaryBasicFrops::new();
    fops.build_table();
    let table = fops.generate_full_table();
    FrequentOpsHelpers::test_all_accessible_values(
        &table,
        BinaryBasicFrops::is_frequent_op,
        BinaryBasicFrops::get_row,
    );
}
